// The program maker.
//
// Builds a REGOL program in the browser and hands it to the phone as a `regol://p?d=...` link:
// the JSON of Formats.ProgramFile, raw-deflated, base64url, exactly as engine/Formats.kt writes
// and reads it. There is no server in this, which is the point - the whole program travels inside
// the link, so it works with the network off, and nothing about anyone's training is sent anywhere.
//
// The lift library is lifts.json, generated by the app's own LiftsExportTest from the same rules
// the app uses when you add a lift from its library. It is shipped rather than reimplemented
// because importProgram matches an incoming lift to one of yours by name and equipment and
// otherwise keeps this record verbatim: a name in the wrong case adds a second Bench Press, and a
// wrong `min` or `perSide` is wrong in a way nobody notices until they load the bar.
(function () {
  'use strict';

  var MAX_CHARS = 2600;           // Formats.programLink's own ceiling
  var DRAFT = 'regol.program.draft';
  var EQUIP = ['Barbell', 'Dumbbell', 'Cable', 'Machine', 'Bodyweight'];

  var lifts = null;               // the library, once fetched
  var byKey = {};                 // name|equip -> row
  var state = null;
  var picking = null;             // which template a picked lift joins

  /* ---------- the program being built ---------- */

  function blank() {
    return { name: '', unit: 'kg', block: null, templates: [], lifts: {}, seq: 0 };
  }
  function id(p) { state.seq += 1; return p + state.seq; }

  function save() {
    try { localStorage.setItem(DRAFT, JSON.stringify(state)); } catch (e) { /* private window, full disk */ }
  }
  function load() {
    try {
      var raw = localStorage.getItem(DRAFT);
      if (!raw) return null;
      var d = JSON.parse(raw);
      return d && d.templates ? d : null;
    } catch (e) { return null; }
  }

  /* ---------- the file the app reads ---------- */

  // One Exercise, as the app would have written it for the same library entry.
  function exercise(exId, row, unit) {
    var e = { id: exId, name: row.n, group: row.g, equip: row.e, unit: unit, min: row.min, inc: row.inc };
    if (row.s) e.secondary = row.s;
    if (row.ps) e.perSide = true;
    if (row.l) e.load = row.l;
    return e;
  }

  // Only what differs from the Kotlin defaults is written, the way encodeDefaults=false does on
  // the other side: every byte saved here is a byte of program that still fits in a code.
  function item(it) {
    var o = { exId: it.exId };
    if (it.sets !== 3) o.sets = it.sets;
    if (it.lo !== 8) o.lo = it.lo;
    if (it.hi !== 10) o.hi = it.hi;
    if (it.rir !== 2) o.rir = it.rir;
    if (it.rest != null) o.rest = it.rest;
    return o;
  }

  function programFile() {
    var used = {};
    state.templates.forEach(function (t) { t.items.forEach(function (i) { used[i.exId] = true; }); });
    var name = (state.name || '').trim() || (state.templates[0] && state.templates[0].name) || 'Program';
    var f = {
      kind: 'program',
      name: name,
      templates: state.templates.map(function (t) {
        return { id: t.id, name: (t.name || '').trim() || 'Workout', items: t.items.map(item) };
      }),
      exercises: Object.keys(used).map(function (k) {
        return exercise(k, state.lifts[k], state.unit);
      }),
    };
    // A single workout travels as a template on its own; the app reads that as one template.
    if (state.templates.length > 1) {
      f.program = { id: 'p', name: name, templateIds: state.templates.map(function (t) { return t.id; }) };
      if (state.block) f.program.block = state.block;
    }
    return f;
  }

  function b64url(buf) {
    var s = '', b = new Uint8Array(buf);
    for (var i = 0; i < b.length; i++) s += String.fromCharCode(b[i]);
    return btoa(s).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
  }

  // Raw deflate, which is Deflater(BEST_COMPRESSION, nowrap = true) on the Kotlin side.
  function link(file) {
    var json = JSON.stringify(file);
    if (!self.CompressionStream) return Promise.resolve({ error: 'old-browser', json: json });
    var stream = new Blob([json]).stream().pipeThrough(new CompressionStream('deflate-raw'));
    return new Response(stream).arrayBuffer().then(function (packed) {
      var url = 'regol://p?d=' + b64url(packed);
      return { url: url, chars: url.length, json: json, over: url.length > MAX_CHARS };
    });
  }

  /* ---------- drawing it ---------- */

  var $ = function (sel, root) { return (root || document).querySelector(sel); };
  var $$ = function (sel, root) { return [].slice.call((root || document).querySelectorAll(sel)); };

  function el(tag, cls, text) {
    var n = document.createElement(tag);
    if (cls) n.className = cls;
    if (text != null) n.textContent = text;
    return n;
  }

  function num(label, value, min, max, onChange) {
    var w = el('div', 'num');
    var l = el('label', null, label);
    var i = document.createElement('input');
    i.type = 'number'; i.value = value; i.min = min; i.max = max;
    i.setAttribute('aria-label', label);
    i.addEventListener('change', function () {
      var v = parseInt(i.value, 10);
      if (isNaN(v)) v = value;
      v = Math.max(min, Math.min(max, v));
      i.value = v;
      onChange(v);
    });
    w.appendChild(l); w.appendChild(i);
    return w;
  }

  function iconBtn(label, path, onClick) {
    var b = el('button', 'icon');
    b.type = 'button';
    b.setAttribute('aria-label', label);
    b.innerHTML = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" ' +
      'stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="' + path + '"/></svg>';
    b.addEventListener('click', onClick);
    return b;
  }

  function drawTemplates() {
    var host = $('[data-templates]');
    host.textContent = '';
    state.templates.forEach(function (t, ti) {
      var card = el('div', 'card');
      card.style.cssText = 'display:flex;flex-direction:column;gap:4px';

      var head = el('div');
      head.style.cssText = 'display:flex;align-items:center;gap:10px;padding-bottom:8px';
      var nameI = document.createElement('input');
      nameI.className = 'inp';
      nameI.value = t.name;
      nameI.maxLength = 30;
      nameI.placeholder = 'Workout name';
      nameI.style.cssText = 'flex:1;height:44px;font:700 20px/1 \'Barlow Condensed\'';
      nameI.setAttribute('aria-label', 'Workout name');
      nameI.addEventListener('input', function () { t.name = nameI.value; save(); refresh(); });
      head.appendChild(nameI);
      if (ti > 0) head.appendChild(iconBtn('Move ' + (t.name || 'workout') + ' up', 'M18 15l-6-6-6 6', function () {
        state.templates.splice(ti - 1, 0, state.templates.splice(ti, 1)[0]); save(); drawTemplates(); refresh();
      }));
      head.appendChild(iconBtn('Remove ' + (t.name || 'this workout'), 'M3 6h18M8 6V4h8v2M6 6l1 14h10l1-14', function () {
        state.templates.splice(ti, 1); save(); drawTemplates(); refresh();
      }));
      card.appendChild(head);

      if (!t.items.length) card.appendChild(el('p', 'note', 'No lifts yet.'));

      t.items.forEach(function (it, ii) {
        var row = el('div', 'row');
        var lift = state.lifts[it.exId];
        var nameBox = el('div', 'row-name');
        nameBox.appendChild(el('b', null, lift.n));
        nameBox.appendChild(el('span', null, lift.e + ' · ' + lift.g));
        row.appendChild(nameBox);

        var nums = el('div', 'nums');
        nums.appendChild(num('SETS', it.sets, 1, 10, function (v) { it.sets = v; save(); refresh(); }));
        nums.appendChild(num('FROM', it.lo, 1, 30, function (v) { it.lo = v; if (it.hi < v) it.hi = v; save(); drawTemplates(); refresh(); }));
        nums.appendChild(num('TO', it.hi, 1, 30, function (v) { it.hi = Math.max(v, it.lo); save(); drawTemplates(); refresh(); }));
        nums.appendChild(num('RIR', it.rir, 0, 5, function (v) { it.rir = v; save(); refresh(); }));
        nums.appendChild(iconBtn('Remove ' + lift.n, 'M3 6h18M8 6V4h8v2M6 6l1 14h10l1-14', function () {
          t.items.splice(ii, 1); save(); drawTemplates(); refresh();
        }));
        row.appendChild(nums);
        card.appendChild(row);
      });

      var add = el('button', 'btn btn-ghost btn-sm', 'Add a lift');
      add.type = 'button';
      add.style.cssText = 'align-self:flex-start;margin-top:12px';
      add.addEventListener('click', function () { openPicker(t); });
      card.appendChild(add);

      host.appendChild(card);
    });
  }

  /* ---------- the lift picker ---------- */

  var pickEquip = {};

  function openPicker(t) {
    picking = t;
    var dlg = $('[data-picker]');
    ensureLibrary().then(function () {
      $('[data-pick-search]').value = '';
      drawPickList();
      dlg.showModal();
      $('[data-pick-search]').focus();
    });
  }

  function ensureLibrary() {
    if (lifts) return Promise.resolve();
    return fetch('lifts.json').then(function (r) { return r.json(); }).then(function (rows) {
      lifts = rows;
      rows.forEach(function (r) { byKey[r.n + '|' + r.e] = r; });
      var host = $('[data-pick-equip]');
      EQUIP.forEach(function (e) {
        var c = el('button', 'chip', e);
        c.type = 'button';
        c.setAttribute('aria-pressed', 'false');
        c.addEventListener('click', function () {
          pickEquip[e] = !pickEquip[e];
          c.setAttribute('aria-pressed', pickEquip[e] ? 'true' : 'false');
          drawPickList();
        });
        host.appendChild(c);
      });
    });
  }

  // How well a row answers the query. Lower is better. The library is sorted by name, so without
  // this, typing the exact name of a lift hands you whatever sorts first among the lifts that
  // happen to contain those words: "barbell squat" opened on Barbell Bench Front Squat.
  function rank(r, q, words) {
    var n = r.n.toLowerCase();
    if (n === q) return 0;
    if (n.indexOf(q) === 0) return 1;
    if (n.indexOf(' ' + q) >= 0) return 2;   // the query starts a word in the name
    if (n.indexOf(q) >= 0) return 3;         // somewhere in the name
    var hay = n + ' ' + r.e.toLowerCase() + ' ' + r.g.toLowerCase();
    for (var w = 0; w < words.length; w++) if (hay.indexOf(words[w]) < 0) return -1;
    return 4;                                // every word, scattered across name, kit and group
  }

  function drawPickList() {
    var q = ($('[data-pick-search]').value || '').trim().toLowerCase();
    var on = EQUIP.filter(function (e) { return pickEquip[e]; });
    var words = q ? q.split(/\s+/) : [];
    var out = [];
    for (var i = 0; i < lifts.length; i++) {
      var r = lifts[i];
      if (on.length && on.indexOf(r.e) < 0) continue;
      if (words.length) {
        var k = rank(r, q, words);
        if (k < 0) continue;
        r = { r: r, k: k };
      } else {
        if (out.length >= 80) break;
        r = { r: r, k: 0 };
      }
      out.push(r);
    }
    // Best answer first, then the shorter name, then alphabetically - the order the file is in.
    if (words.length) out.sort(function (a, b) { return a.k - b.k || a.r.n.length - b.r.n.length; });
    out = out.slice(0, 80).map(function (x) { return x.r; });
    var host = $('[data-pick-list]');
    host.textContent = '';
    if (!out.length) { host.appendChild(el('p', 'note', 'Nothing matches that.')); return; }
    out.forEach(function (r) {
      var b = el('button', 'pick-item');
      b.type = 'button';
      b.appendChild(el('b', null, r.n));
      b.appendChild(el('span', null, r.e + ' · ' + r.g + (r.s ? ', ' + r.s.join(', ') : '')));
      b.addEventListener('click', function () { addLift(r); });
      host.appendChild(b);
    });
  }

  function addLift(row) {
    var key = row.n + '|' + row.e;
    var exId = null;
    // One record per lift across the whole program, so two workouts sharing a lift share its id.
    Object.keys(state.lifts).forEach(function (k) {
      if (state.lifts[k].n === row.n && state.lifts[k].e === row.e) exId = k;
    });
    if (!exId) { exId = id('x'); state.lifts[exId] = row; }
    picking.items.push({ exId: exId, sets: 3, lo: 8, hi: 10, rir: 2 });
    save();
    $('[data-picker]').close();
    drawTemplates();
    refresh();
  }

  /* ---------- what you are about to send ---------- */

  function refresh() {
    var side = $('[data-summary]');
    var open = $('[data-act="open"]'), copy = $('[data-act="copy"]'), file = $('[data-act="file"]');
    var big = $('[data-too-big]'), size = $('[data-size]');
    var sets = 0, nLifts = 0;
    var seen = {};
    state.templates.forEach(function (t) {
      t.items.forEach(function (i) { sets += i.sets; if (!seen[i.exId]) { seen[i.exId] = 1; nLifts++; } });
    });

    if (!state.templates.length || !sets) {
      side.textContent = 'Nothing to send yet.';
      open.hidden = true; copy.disabled = true; file.disabled = true;
      big.hidden = true; size.textContent = '';
      return;
    }

    var n = state.templates.length;
    // The app's own arithmetic for "about 45 minutes": three minutes a working set, rest included.
    side.textContent = n + (n === 1 ? ' workout · ' : ' workouts · ') + nLifts +
      (nLifts === 1 ? ' lift · ' : ' lifts · ') + sets + ' working sets · about ' + (sets * 3) +
      ' minutes a session';

    link(programFile()).then(function (r) {
      if (r.error === 'old-browser') {
        big.hidden = false;
        big.textContent = 'This browser cannot make the code. Use the file instead, or open this page in a newer browser.';
        open.hidden = true; copy.disabled = true; file.disabled = false;
        return;
      }
      size.textContent = r.chars + ' of ' + MAX_CHARS + ' characters';
      if (r.over) {
        big.hidden = false;
        big.textContent = 'This program is too big to travel as a code - ' + r.chars + ' characters against the ' +
          MAX_CHARS + ' a code holds. Send the file instead, or take a workout out.';
        open.hidden = true; copy.disabled = true;
      } else {
        big.hidden = true;
        open.hidden = false; open.href = r.url; copy.disabled = false;
      }
      file.disabled = false;
      refresh.last = r;
    });
  }

  /* ---------- starting points ---------- */

  function scratch() {
    state = blank();
    state.name = 'My program';
    state.templates.push({ id: id('t'), name: 'Workout A', items: [] });
    save();
    paintTop();
    drawTemplates();
    refresh();
  }

  function paintTop() {
    $('[data-prog-name]').value = state.name;
    $$('[data-unit]').forEach(function (b) {
      b.setAttribute('aria-pressed', b.getAttribute('data-unit') === state.unit ? 'true' : 'false');
    });
  }

  function download() {
    var f = programFile();
    var blob = new Blob([JSON.stringify(f, null, 1)], { type: 'application/json' });
    var a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = (f.name || 'program').replace(/[^\w -]+/g, '').trim().replace(/\s+/g, '-').toLowerCase() + '.regol';
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(function () { URL.revokeObjectURL(a.href); }, 2000);
  }

  function start() {
    var saved = load();
    state = saved || blank();
    if (saved) {
      var note = $('[data-draft]');
      note.hidden = false;
      note.textContent = 'Picked up where you left off. ';
      var b = el('button', 'btn btn-sm btn-ghost', 'Start again');
      b.type = 'button';
      b.style.cssText = 'height:34px;padding:0 12px;font-size:13px;margin-left:8px';
      b.addEventListener('click', function () {
        try { localStorage.removeItem(DRAFT); } catch (e) {}
        note.hidden = true;
        scratch();
      });
      note.appendChild(b);
    }
    paintTop();
    drawTemplates();
    refresh();

    $('[data-prog-name]').addEventListener('input', function (e) { state.name = e.target.value; save(); refresh(); });
    $$('[data-unit]').forEach(function (b) {
      b.addEventListener('click', function () { state.unit = b.getAttribute('data-unit'); paintTop(); save(); refresh(); });
    });
    $('[data-act="scratch"]').addEventListener('click', scratch);
    $('[data-act="add-template"]').addEventListener('click', function () {
      var names = ['Workout A', 'Workout B', 'Workout C', 'Workout D', 'Workout E', 'Workout F'];
      state.templates.push({ id: id('t'), name: names[state.templates.length] || 'Workout', items: [] });
      save(); drawTemplates(); refresh();
    });
    $('[data-act="close-pick"]').addEventListener('click', function () { $('[data-picker]').close(); });
    $('[data-pick-search]').addEventListener('input', drawPickList);
    $('[data-act="file"]').addEventListener('click', download);
    $('[data-act="copy"]').addEventListener('click', function () {
      var r = refresh.last;
      if (!r || !r.url) return;
      var btn = $('[data-act="copy"]');
      navigator.clipboard.writeText(r.url).then(function () {
        var was = btn.textContent;
        btn.textContent = 'Copied';
        setTimeout(function () { btn.textContent = was; }, 1600);
      });
    });
    // The questionnaire is the next piece. A button that opens an apology is worse than a
    // button that says plainly it is not here yet.
    var gen = $('[data-act="generate"]');
    gen.disabled = true;
    gen.textContent = 'Answer six questions - not built yet';
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start);
  else start();
})();
